const std = @import("std");
const Value = std.json.Value;
fn eq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}
fn number(v: Value) !f64 {
    return switch (v) {
        .integer => |n| @floatFromInt(n),
        .float => |n| n,
        else => error.InvalidAmount,
    };
}
fn name(v: Value) []const u8 {
    return v.object.get("name").?.string;
}
pub const RestAPI = struct {
    allocator: std.mem.Allocator,
    arena: std.heap.ArenaAllocator,
    users: std.json.Array,
    pub fn init(a: std.mem.Allocator, database: ?[]const u8) !RestAPI {
        var arena = std.heap.ArenaAllocator.init(a);
        errdefer arena.deinit();
        const aa = arena.allocator();
        var users = std.json.Array.init(aa);
        if (database) |encoded| {
            const db = try std.json.parseFromSliceLeaky(Value, aa, encoded, .{ .allocate = .alloc_always });
            if (db != .object) return error.InvalidDatabase;
            const values = db.object.get("users") orelse return error.InvalidDatabase;
            if (values != .array) return error.InvalidDatabase;
            users = values.array;
        }
        return .{ .allocator = a, .arena = arena, .users = users };
    }
    pub fn deinit(api: *RestAPI) void {
        api.arena.deinit();
    }
    fn payload(api: *RestAPI, encoded: []const u8) !Value {
        const value = try std.json.parseFromSliceLeaky(Value, api.arena.allocator(), encoded, .{ .allocate = .alloc_always });
        if (value != .object) return error.InvalidPayload;
        return value;
    }
    fn user(api: *RestAPI, wanted: []const u8) ?*Value {
        for (api.users.items) |*u| {
            if (eq(name(u.*), wanted)) return u;
        }
        return null;
    }
    fn response(api: *RestAPI, selected: []const Value) ![]u8 {
        const a = api.arena.allocator();
        var array = std.json.Array.init(a);
        try array.appendSlice(selected);
        std.mem.sort(Value, array.items, {}, struct {
            fn less(_: void, x: Value, y: Value) bool {
                return std.mem.order(u8, name(x), name(y)) == .lt;
            }
        }.less);
        var object: std.json.ObjectMap = .{};
        try object.put(a, "users", .{ .array = array });
        return std.json.Stringify.valueAlloc(api.allocator, Value{ .object = object }, .{});
    }
    pub fn get(api: *RestAPI, url: []const u8, encoded: ?[]const u8) ![]u8 {
        if (!eq(url, "/users")) return error.UnknownRoute;
        if (encoded) |json| {
            const p = try api.payload(json);
            const names = p.object.get("users") orelse return error.InvalidPayload;
            if (names != .array) return error.InvalidPayload;
            var selected = std.json.Array.init(api.arena.allocator());
            for (names.array.items) |n| {
                if (n != .string) return error.InvalidPayload;
                const u = api.user(n.string) orelse return error.UnknownUser;
                try selected.append(u.*);
            }
            return api.response(selected.items);
        }
        return api.response(api.users.items);
    }
    fn balance(u: *Value) !void {
        var sum: f64 = 0;
        for (u.object.get("owed_by").?.object.values()) |v| sum += try number(v);
        for (u.object.get("owes").?.object.values()) |v| sum -= try number(v);
        u.object.getPtr("balance").?.* = .{ .float = sum };
    }
    fn setDebt(a: std.mem.Allocator, u: *Value, other: []const u8, amount: f64) !void {
        const owes = &u.object.getPtr("owes").?.object;
        const owed = &u.object.getPtr("owed_by").?.object;
        _ = owes.swapRemove(other);
        _ = owed.swapRemove(other);
        if (amount > 0) try owed.put(a, other, .{ .float = amount });
        if (amount < 0) try owes.put(a, other, .{ .float = -amount });
        try balance(u);
    }
    pub fn post(api: *RestAPI, url: []const u8, encoded: []const u8) ![]u8 {
        const p = try api.payload(encoded);
        const a = api.arena.allocator();
        if (eq(url, "/add")) {
            const n = p.object.get("user") orelse return error.InvalidPayload;
            if (n != .string) return error.InvalidPayload;
            if (api.user(n.string) != null) return error.DuplicateUser;
            var object: std.json.ObjectMap = .{};
            try object.put(a, "name", n);
            try object.put(a, "owes", .{ .object = .{} });
            try object.put(a, "owed_by", .{ .object = .{} });
            try object.put(a, "balance", .{ .float = 0 });
            const u = Value{ .object = object };
            // Array allocations must use the arena at its current, stable address.
            api.users.allocator = a;
            try api.users.append(u);
            return std.json.Stringify.valueAlloc(api.allocator, u, .{});
        }
        if (!eq(url, "/iou")) return error.UnknownRoute;
        const ln = p.object.get("lender") orelse return error.InvalidPayload;
        const bn = p.object.get("borrower") orelse return error.InvalidPayload;
        const amount = try number(p.object.get("amount") orelse return error.InvalidPayload);
        if (ln != .string or bn != .string or amount < 0 or eq(ln.string, bn.string)) return error.InvalidPayload;
        const lender = api.user(ln.string) orelse return error.UnknownUser;
        const borrower = api.user(bn.string) orelse return error.UnknownUser;
        var net = amount;
        if (lender.object.get("owed_by").?.object.get(bn.string)) |v| net += try number(v);
        if (lender.object.get("owes").?.object.get(bn.string)) |v| net -= try number(v);
        try setDebt(a, lender, name(borrower.*), net);
        try setDebt(a, borrower, name(lender.*), -net);
        return api.response(&.{ lender.*, borrower.* });
    }
};

