const std = @import("std");
pub const RestAPI = struct {
    pub fn init(a: std.mem.Allocator, d: ?[]const u8) !RestAPI {
        _ = a;
        _ = d;
        return .{};
    }
    pub fn deinit(a: *RestAPI) void {
        _ = a;
    }
    pub fn get(a: *RestAPI, u: []const u8, p: ?[]const u8) ![]u8 {
        _ = a;
        _ = u;
        _ = p;
        return error.NotImplemented;
    }
    pub fn post(a: *RestAPI, u: []const u8, p: []const u8) ![]u8 {
        _ = a;
        _ = u;
        _ = p;
        return error.NotImplemented;
    }
};

tests.test_rest_api.zig:
// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("rest_api.zig");
const V = std.json.Value;
fn numeric(v: V) f64 {
    return switch (v) {
        .float => |n| n,
        .integer => |n| @floatFromInt(n),
        else => unreachable,
    };
}
fn same(a: V, b: V) anyerror!void {
    if ((a == .float or a == .integer) and (b == .float or b == .integer)) {
        try t.expectApproxEqAbs(numeric(b), numeric(a), 0.000001);
        return;
    }
    try t.expectEqual(std.meta.activeTag(b), std.meta.activeTag(a));
    switch (a) {
        .object => |o| {
            try t.expectEqual(b.object.count(), o.count());
            var it = o.iterator();
            while (it.next()) |e| {
                try t.expect(b.object.contains(e.key_ptr.*));
                try same(e.value_ptr.*, b.object.get(e.key_ptr.*).?);
            }
        },
        .array => |arr| {
            try t.expectEqual(b.array.items.len, arr.items.len);
            for (arr.items, b.array.items) |x, y| try same(x, y);
        },
        .string => |s| try t.expectEqualStrings(b.string, s),
        .bool => |x| try t.expectEqual(b.bool, x),
        .null => {},
        else => unreachable,
    }
}
fn check(actual: []const u8, expected: []const u8) !void {
    const a = try std.json.parseFromSlice(V, t.allocator, actual, .{});
    defer a.deinit();
    const b = try std.json.parseFromSlice(V, t.allocator, expected, .{});
    defer b.deinit();
    try same(a.value, b.value);
}
test "no users" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": []}");
    defer api.deinit();
    const response = try api.get("/users", null);
    defer t.allocator.free(response);
    try check(response, "{\"users\": []}");
}
test "add user" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": []}");
    defer api.deinit();
    const response = try api.post("/add", "{\"user\": \"Adam\"}");
    defer t.allocator.free(response);
    try check(response, "{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}");
}
test "get single user" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}, {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}]}");
    defer api.deinit();
    const response = try api.get("/users", "{\"users\": [\"Bob\"]}");
    defer t.allocator.free(response);
    try check(response, "{\"users\": [{\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}]}");
}
test "both users have 0 balance" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}, {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}]}");
    defer api.deinit();
    const response = try api.post("/iou", "{\"lender\": \"Adam\", \"borrower\": \"Bob\", \"amount\": 3.0}");
    defer t.allocator.free(response);
    try check(response, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {\"Bob\": 3.0}, \"balance\": 3.0}, {\"name\": \"Bob\", \"owes\": {\"Adam\": 3.0}, \"owed_by\": {}, \"balance\": -3.0}]}");
}
test "borrower has negative balance" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}, {\"name\": \"Bob\", \"owes\": {\"Chuck\": 3.0}, \"owed_by\": {}, \"balance\": -3.0}, {\"name\": \"Chuck\", \"owes\": {}, \"owed_by\": {\"Bob\": 3.0}, \"balance\": 3.0}]}");
    defer api.deinit();
    const response = try api.post("/iou", "{\"lender\": \"Adam\", \"borrower\": \"Bob\", \"amount\": 3.0}");
    defer t.allocator.free(response);
    try check(response, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {\"Bob\": 3.0}, \"balance\": 3.0}, {\"name\": \"Bob\", \"owes\": {\"Adam\": 3.0, \"Chuck\": 3.0}, \"owed_by\": {}, \"balance\": -6.0}]}");
}
test "lender has negative balance" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}, {\"name\": \"Bob\", \"owes\": {\"Chuck\": 3.0}, \"owed_by\": {}, \"balance\": -3.0}, {\"name\": \"Chuck\", \"owes\": {}, \"owed_by\": {\"Bob\": 3.0}, \"balance\": 3.0}]}");
    defer api.deinit();
    const response = try api.post("/iou", "{\"lender\": \"Bob\", \"borrower\": \"Adam\", \"amount\": 3.0}");
    defer t.allocator.free(response);
    try check(response, "{\"users\": [{\"name\": \"Adam\", \"owes\": {\"Bob\": 3.0}, \"owed_by\": {}, \"balance\": -3.0}, {\"name\": \"Bob\", \"owes\": {\"Chuck\": 3.0}, \"owed_by\": {\"Adam\": 3.0}, \"balance\": 0.0}]}");
}
test "lender owes borrower" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": [{\"name\": \"Adam\", \"owes\": {\"Bob\": 3.0}, \"owed_by\": {}, \"balance\": -3.0}, {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {\"Adam\": 3.0}, \"balance\": 3.0}]}");
    defer api.deinit();
    const response = try api.post("/iou", "{\"lender\": \"Adam\", \"borrower\": \"Bob\", \"amount\": 2.0}");
    defer t.allocator.free(response);
    try check(response, "{\"users\": [{\"name\": \"Adam\", \"owes\": {\"Bob\": 1.0}, \"owed_by\": {}, \"balance\": -1.0}, {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {\"Adam\": 1.0}, \"balance\": 1.0}]}");
}
test "lender owes borrower less than new loan" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": [{\"name\": \"Adam\", \"owes\": {\"Bob\": 3.0}, \"owed_by\": {}, \"balance\": -3.0}, {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {\"Adam\": 3.0}, \"balance\": 3.0}]}");
    defer api.deinit();
    const response = try api.post("/iou", "{\"lender\": \"Adam\", \"borrower\": \"Bob\", \"amount\": 4.0}");
    defer t.allocator.free(response);
    try check(response, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {\"Bob\": 1.0}, \"balance\": 1.0}, {\"name\": \"Bob\", \"owes\": {\"Adam\": 1.0}, \"owed_by\": {}, \"balance\": -1.0}]}");
}
test "lender owes borrower same as new loan" {
    var api = try m.RestAPI.init(t.allocator, "{\"users\": [{\"name\": \"Adam\", \"owes\": {\"Bob\": 3.0}, \"owed_by\": {}, \"balance\": -3.0}, {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {\"Adam\": 3.0}, \"balance\": 3.0}]}");
    defer api.deinit();
    const response = try api.post("/iou", "{\"lender\": \"Adam\", \"borrower\": \"Bob\", \"amount\": 3.0}");
    defer t.allocator.free(response);
    try check(response, "{\"users\": [{\"name\": \"Adam\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}, {\"name\": \"Bob\", \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}]}");
}
test "updates persist across requests and unknown routes fail" {
    var api = try m.RestAPI.init(t.allocator, null);
    defer api.deinit();
    const a = try api.post("/add", "{\"user\":\"A\"}");
    defer t.allocator.free(a);
    const b = try api.post("/add", "{\"user\":\"B\"}");
    defer t.allocator.free(b);
    const c = try api.post("/iou", "{\"lender\":\"B\",\"borrower\":\"A\",\"amount\":5}");
    defer t.allocator.free(c);
    const d = try api.get("/users", null);
    defer t.allocator.free(d);
    try check(c, d);
    try t.expectError(error.UnknownRoute, api.get("/missing", null));
    try t.expectError(error.DuplicateUser, api.post("/add", "{\"user\":\"A\"}"));
}
